import { createRouter, RouterProvider } from "@tanstack/react-router";
import { useState } from "react";
import { Loading } from "./components/Loading";
import { RootErrorBoundary } from "./components/RootErrorBoundary";
import { useAuth } from "./hooks/useAuth";
// NOTE: The routeTree is generated by a vite plugin (@tanstack/router-plugin/vite)
// So do not edit it manually.
import { routeTree } from "./routeTree.gen";
import type { OnboardingStep } from "./types";

interface HydratedReact {
  onboarding: OnboardingStep;
}

declare var hydrateReact: HydratedReact;

export const router = createRouter({
  routeTree,
  context: {
    auth: {
      isLoggedIn: false,
      currentUser: undefined,
    },
    onboarding: {
      step: null,
      setStep(_step) {},
    },
  },
  defaultPendingComponent: Loading,
  defaultErrorComponent: RootErrorBoundary,
  defaultPreload: false,
});

export function Router() {
  const { isLoggedIn, currentUser } = useAuth();
  const [onboardingStep, setOnboardingStep] = useState<OnboardingStep>(
    hydrateReact.onboarding,
  );

  const context = {
    auth: {
      isLoggedIn,
      currentUser,
    },
    onboarding: {
      step: onboardingStep,
      setStep: setOnboardingStep,
    },
  };

  return <RouterProvider router={router} context={context} />;
}
